import {safeRoute} from '../ranch-navigation.mjs';
import {hexBounds} from '../simulation/spatial-bounds.mjs';
export const GAME_DAY_SECONDS=6,VIP_DELAY_DAYS=7;
export function ensureFerrySchedule(state){return state.rocket.schedule??=( {nextArrival:(Math.floor(state.seconds/180)+1)*180,lastArrival:Math.floor(state.seconds/180)*180,totalDelayDays:0,holding:false} );}
export function vipActive(state){return !!state.rocket.vip&&!['home'].includes(state.rocket.vip.phase);}
export function vipAvailability(state,plan){if(plan.placements.find(p=>p.id==='landing')?.ship!=='RE-073')return {ready:false,label:'VIP ship needs an 80 m Moonbase pad'};if(vipActive(state))return {ready:false,label:'VIP visit in progress'};if(state.rocket.dispatch)return {ready:false,label:'Wait for the supply dropship'};return {ready:true,label:'Call our VIP ship'};}
const members=[['vip-you','You','VIP'],['vip-party','Your companion','VIP'],['vip-guide','Tour guide','Retinue'],['vip-aide','Aide','Retinue'],['vip-guard','Honor guard','Retinue']];
const seatPositions=[[-.9,-3.35],[.9,-3.35],[-1.95,-.05],[1.95,-.05],[-1.95,1.25]];
function move(person,path,dt,speed=1.25){let budget=dt*speed;person.moving=false;while(budget>0&&person.index<path.length){const q=path[person.index],dx=q.x-person.position.x,dz=q.z-person.position.z,dy=(q.y??person.position.y??0)-(person.position.y??0),d=Math.hypot(dx,dz,dy),step=Math.min(d,budget);if(d>1e-8){person.position.x+=dx/d*step;person.position.z+=dz/d*step;if(q.y!==undefined)person.position.y=(person.position.y??0)+dy/d*step;person.heading=Math.atan2(dx,dz);person.moving=true;}budget-=step;if(d<=step+1e-8)person.index++;else break;}return person.index>=path.length;}
function boardingPath(plan){const p=plan.placements.find(p=>p.id==='landing'),deck=plan.heightAt(p.x,p.z)+p.deck;return {p,deck,points:[{x:p.x,z:p.z,y:deck+2.6},{x:p.x,z:p.z+1.3,y:deck+2.6},{x:p.x+2.75,z:p.z+1.3,y:deck+2.6},...[5,4,3,2,1,0].map(i=>({x:p.x+4.32-i*.27,z:p.z+1.3,y:deck+1.25+(i+1)*.225})),{x:p.x+5.1,z:p.z+1.3,y:deck+.65},{x:p.x+6,z:p.z+1.3,y:plan.heightAt(p.x+6,p.z+1.3)},{x:p.x+9.1,z:p.z+1.3,y:plan.heightAt(p.x+9.1,p.z+1.3)}]};}
function tourRoute(plan,origin){const obstacles=plan.placements.map(p=>({...p})),bounds=hexBounds(plan.radius),targets=['greenhouse','lab','habitat'].map(id=>{const p=plan.placements.find(x=>x.id===id);return {id,label:p.label,x:p.x,z:p.z+p.radius+1.6};});const stops=[];let from=origin;for(const target of [...targets,{id:'return',label:'Return to Aurora',...origin}]){const path=safeRoute(from,[target],.55,obstacles,bounds);if(!path)return null;stops.push({...target,path:path.map(p=>({...p,y:plan.heightAt(p.x,p.z)}))});from=target;}return stops;}
export function requestVip(state,plan,regularPhase){if(!vipAvailability(state,plan).ready)return false;const {p,deck,points}=boardingPath(plan),origin=points.at(-1),stops=tourRoute(plan,origin);if(!stops)return false;const s=ensureFerrySchedule(state),f=regularPhase;const clears=f.phase!=='in-transit'?16:0;state.rocket.vip={id:(state.rocket.vip?.id??0)+1,phase:clears?'waiting-for-pad':'descending',started:state.seconds,phaseStarted:state.seconds,landingAt:state.seconds+clears+16,flightStart:state.seconds+clears,clearance:clears,deck,port:{x:p.x,z:p.z},boarding:points,stops,stop:0,trail:[],people:members.map(([id,name,role],i)=>({id,name,role,position:{x:p.x+seatPositions[i][0],z:p.z-seatPositions[i][1],y:deck+2.43},seat:seatPositions[i],heading:0,index:0,moving:false,seated:true})),events:[{type:'called',at:state.seconds}],returnedHome:false};if(clears)state.rocket.yieldFlight={started:state.seconds,altitude:f.altitude};s.nextArrival+=VIP_DELAY_DAYS*GAME_DAY_SECONDS;s.totalDelayDays+=VIP_DELAY_DAYS;s.lastDelay={days:VIP_DELAY_DAYS,at:state.seconds,reason:'VIP priority arrival'};return true;}
export function vipFlight(state){const v=state.rocket.vip;if(!v||v.phase==='home')return {phase:'in-transit',altitude:38,thrust:0};if(v.phase==='waiting-for-pad')return {phase:'in-transit',altitude:38,thrust:0};if(v.phase==='descending'){const q=Math.max(0,Math.min(1,(v.landingAt-state.seconds)/16));return {phase:'descending',altitude:38*q*q,thrust:.4+.6*q};}if(v.phase==='ascending'){const q=Math.min(1,(state.seconds-v.phaseStarted)/16);return {phase:'ascending',altitude:38*q*q,thrust:1};}return {phase:'docked',altitude:0,thrust:0};}
function phase(v,name,now){v.phase=name;v.phaseStarted=now;v.events.push({type:name,at:now});for(const p of v.people){p.index=0;p.moving=false;}}
export function advanceVip(state,plan,dt){const v=state.rocket.vip;if(!v||v.phase==='home')return;const now=state.seconds;
 if(v.phase==='waiting-for-pad'){if(now>=v.flightStart)phase(v,'descending',now);return;}
 if(v.phase==='descending'){if(now>=v.landingAt){phase(v,'disembarking',now);}return;}
 if(v.phase==='disembarking'){let done=true;for(const [i,p] of v.people.entries()){if(now-v.phaseStarted<i*1.3){done=false;continue;}if(p.seated){p.seated=false;p.position.y=v.deck+2.6;}const route=[{x:v.port.x,z:p.position.z,y:v.deck+2.6},...v.boarding,{x:v.boarding.at(-1).x+(i%2)*1.15,z:v.boarding.at(-1).z+Math.floor(i/2)*1.3,y:plan.heightAt(v.boarding.at(-1).x+(i%2)*1.15,v.boarding.at(-1).z+Math.floor(i/2)*1.3)}];done=move(p,route,dt)&&done;}if(done)phase(v,'greeting',now);return;}
 if(v.phase==='greeting'){const coming=state.colony.residents.filter(p=>p.welcomeVisit===v.id);if(coming.some(p=>p.phase==='welcoming')||!coming.length||now-v.phaseStarted>=60)phase(v,'celebrating',now);return;}
 if(v.phase==='celebrating'){if(now-v.phaseStarted>=12){phase(v,'touring',now);v.stop=0;}return;}
 if(v.phase==='touring'||v.phase==='returning'){const leader=v.people[0],stop=v.stops[v.stop],done=move(leader,stop.path,dt);v.trail.push({...leader.position});if(v.trail.length>600)v.trail.shift();for(let i=1;i<v.people.length;i++){const p=v.people[i],target=v.trail[Math.max(0,v.trail.length-1-i*7)]??leader.position;p.index=0;move(p,[target],dt,1.38);}if(done){if(stop.id==='return'){phase(v,'boarding',now);for(const p of v.people)p.path=[{...v.boarding.at(-1)},...v.boarding.slice().reverse(),{x:v.port.x+p.seat[0],z:v.port.z-p.seat[1],y:v.deck+2.6}];}else phase(v,'tour-stop',now);}return;}
 if(v.phase==='tour-stop'){for(let i=1;i<v.people.length;i++){const p=v.people[i],leader=v.people[0];p.index=0;move(p,[{x:leader.position.x+(i%2?-.9:.9),z:leader.position.z+Math.ceil(i/2)*1.0,y:leader.position.y}],dt);}if(now-v.phaseStarted>=8){v.stop++;phase(v,v.stops[v.stop].id==='return'?'returning':'touring',now);}return;}
 if(v.phase==='boarding'){let done=true;for(const [i,p]of v.people.entries()){if(now-v.phaseStarted<i*1.3){done=false;continue;}if(!p.seated&&move(p,p.path,dt)){p.seated=true;p.position.y=v.deck+2.43;p.heading=0;}done=done&&p.seated;}if(done)phase(v,'ascending',now);return;}
 if(v.phase==='ascending'&&now-v.phaseStarted>=16){phase(v,'home',now);v.returnedHome=true;state.rocket.vipVisits=(state.rocket.vipVisits??0)+1;const s=ensureFerrySchedule(state);if(s.nextArrival<now+16){s.extraPadHoldSeconds=(s.extraPadHoldSeconds??0)+(now+16-s.nextArrival);s.nextArrival=now+16;}s.holding=false;}
}

const accessCache=new WeakMap();
export function vipAccessClearance(plan,x,z){
 if(plan.placements.find(p=>p.id==='landing')?.ship!=='RE-073')return false;
 let segments=accessCache.get(plan);if(!segments){const {points}=boardingPath(plan),stops=tourRoute(plan,points.at(-1));segments=[];if(stops){let from=points.at(-1);for(const stop of stops)for(const to of stop.path){segments.push([from,to]);from=to;}}segments.push([points.at(-1),points.at(-1)]);accessCache.set(plan,segments);}
 return segments.some(([a,b])=>{const dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/(dx*dx+dz*dz||1)));return Math.hypot(x-a.x-t*dx,z-a.z-t*dz)<(a===b?4.5:2.2);});
}
